package com.example.rokidgeminisecretary;
import org.json.*;import java.time.*;
final class CalendarReviewSummary {
 static String describe(JSONObject c){StringBuilder out=new StringBuilder("登録先："+c.optString("calendar_name"));JSONArray events=c.optJSONArray("events");if(events==null||events.length()==0)return out.append("\n予定がありません。登録はできません").toString();for(int i=0;i<Math.min(10,events.length());i++){JSONObject e=events.optJSONObject(i);if(e==null)continue;out.append("\n").append(i+1).append(". ").append(e.optString("title")).append("\n");try{if(e.optBoolean("all_day")){LocalDate start=LocalDate.parse(e.getString("start")),end=LocalDate.parse(e.getString("end"));if(!end.isAfter(start))throw new IllegalArgumentException();out.append("終日 ").append(start).append(" 〜 ").append(end.minusDays(1)).append("（最終日まで）");}else{OffsetDateTime a=OffsetDateTime.parse(e.getString("start")),b=OffsetDateTime.parse(e.getString("end"));if(!b.isAfter(a))throw new IllegalArgumentException();out.append(a.atZoneSameInstant(ZoneId.of("Asia/Tokyo"))).append(" 〜 ").append(b.atZoneSameInstant(ZoneId.of("Asia/Tokyo")));}}catch(Exception bad){out.append("日時が未確定・不正です。修正してください");}if(!e.optString("location").isEmpty())out.append("\n場所：").append(e.optString("location"));}return out.toString();}
 static String diff(JSONObject before,JSONObject after){StringBuilder out=new StringBuilder();if(!before.optString("calendar_name").equals(after.optString("calendar_name")))out.append("登録先：").append(before.optString("calendar_name")).append(" → ").append(after.optString("calendar_name")).append("\n");JSONArray a=before.optJSONArray("events"),b=after.optJSONArray("events");if(a==null||b==null||a.length()!=b.length())return "予定件数が変わっています。候補を取り直してください。";for(int i=0;i<a.length();i++)if(a.optJSONObject(i)==null||b.optJSONObject(i)==null)return "不正な予定があります。候補を取り直してください。";String[] keys={"title","start","end","location","all_day"},names={"予定名","開始","終了","場所","終日"};for(int i=0;i<a.length();i++)for(int j=0;j<keys.length;j++){String old=String.valueOf(a.optJSONObject(i).opt(keys[j])),next=String.valueOf(b.optJSONObject(i).opt(keys[j]));if(!old.equals(next))out.append("予定").append(i+1).append(" ").append(names[j]).append("：").append(old).append(" → ").append(next).append("\n");}return out.length()==0?"変更はありません。":out.toString();}
 private CalendarReviewSummary(){}
}
